head.script:

scwin.onpageload = function() {
};

scwin.onpageunload = function() {

};

scwin.checkVal1 = function(){
	return WebSquare.wUnit.getDomById('wq_uuid_1_itemTable').style.display == 'block';
} 	
scwin.unitTest = function(){
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_btn_submenu').click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest();
